CREATE TABLE device_capabilities(owner_id uuid NOT NULL REFERENCES owners(id),device_id uuid NOT NULL REFERENCES devices(id),capability text NOT NULL,state text NOT NULL,detail jsonb NOT NULL DEFAULT '{}',revision integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(device_id,capability));
CREATE TABLE system_policies(owner_id uuid NOT NULL REFERENCES owners(id),actor_id uuid NOT NULL REFERENCES world_characters(id) DEFERRABLE,device_id uuid NOT NULL REFERENCES devices(id),action text NOT NULL,enabled boolean NOT NULL DEFAULT false,revision integer NOT NULL DEFAULT 1,PRIMARY KEY(actor_id,device_id,action));
CREATE TABLE system_actions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES owners(id),actor_id uuid NOT NULL REFERENCES world_characters(id) DEFERRABLE,device_id uuid NOT NULL REFERENCES devices(id),action text NOT NULL,payload jsonb NOT NULL,payload_hash text NOT NULL,policy_revision integer NOT NULL,state text NOT NULL DEFAULT 'pending',external_id text,result jsonb,revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE today_sources(owner_id uuid NOT NULL REFERENCES owners(id),device_id uuid NOT NULL REFERENCES devices(id),source text NOT NULL,state text NOT NULL,data jsonb,detail text,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(device_id,source));
CREATE TABLE share_drafts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES owners(id),actor_id uuid NOT NULL REFERENCES world_characters(id) DEFERRABLE,room_id uuid NOT NULL REFERENCES rooms(id) DEFERRABLE,content text NOT NULL,asset_ids uuid[] NOT NULL DEFAULT '{}',state text NOT NULL DEFAULT 'draft',run_id uuid REFERENCES runs(id) DEFERRABLE,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE share_draft_assets(draft_id uuid NOT NULL REFERENCES share_drafts(id) DEFERRABLE,asset_id uuid NOT NULL REFERENCES assets(id) DEFERRABLE,PRIMARY KEY(draft_id,asset_id));
